-- ============================================================================
-- B5 FOLLOW-ON W3 (Suite Full precision): rotating capstone brief.
--
-- Plan of record: docs/graded-field-audit/FOLLOW-ON-PROGRAMME.md section 2 and
-- the section 1 Suite rows, decision D3 (owner approved D1 to D7 as
-- recommended, 2026-09-21). The Suite app the capstone is read in gains a
-- "Full precision" switch, off by default, that prints the graded quantities
-- at the precision they are graded to. The brief now says to switch it on.
--
-- BEGINNER
--   Fields read with the switch on: escravos_duty_flow_gpm,
--   escravos_duty_head_ft, escravos_hydraulic_hp, escravos_brake_hp,
--   escravos_motor_input_kw, escravos_discharge_psi.
--   The Duty Point cards round flow and head to whole units and power to 1
--   decimal against tolerances of 5e-7 to 1e-4; there was no discharge pressure
--   stat.
--   APPENDED: Read the figures in the Pump Station Designer with its Full
--   precision switch on (at the top of the page): it prints them to the
--   precision this capstone grades, with no digit grouping.
--
-- INTERMEDIATE
--   Fields read with the switch on: bonga_speed_flow_gpm, bonga_speed_head_ft,
--   bonga_parallel_flow_gpm.
--   The change card rounds flow and head to whole units against tolerances of
--   1e-5 and 1e-4.
--   APPENDED: Read the figures in the Pump Station Designer with its Full
--   precision switch on (at the top of the page): it prints them to the
--   precision this capstone grades, with no digit grouping.
--
-- ADVANCED
--   Fields read with the switch on: bonny_stage1_poly_head, bonny_stage1_gas_hp,
--   bonny_fuel_mmscfd.
--   The cards round head and gas hp to whole units and fuel to 3 decimals
--   against tolerances of 1e-9 to 0.01.
--   APPENDED: Read the figures in the Compressor Station Designer with its Full
--   precision switch on (at the top of the page): it prints them to the
--   precision this capstone grades, with no digit grouping.
--
-- WHAT DOES NOT MOVE. `fields` (every key, label, unit, expected and
-- tolerance, and their order), title, dataset, status and the row. The guard
-- requires `fields` to equal its post-W1 value exactly, before and after, so
-- no answer grades differently and no attempts guard is needed.
--
-- ORDER. Apply only once the Suite build carrying the W3 switch is live (the
-- brief names it). Runs after W1 (20261024*): refuses without it.
--
-- GUARDS. Each prompt must hold its post-W1 text (md5, rewritten) or its W3
-- text (left alone), with the exact fields. Anything else raises and the file
-- rolls back. Generated by docs/graded-field-audit/w3_capstones.py from
-- w3/rotating.json. SAFE TO RE-RUN: a second run writes nothing.
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_s0       text;
  v_s1       text;
  v_s2       text;
begin
  -- rotating / beginner
  select count(*) into v_n from public.academy_capstones where app_slug = 'rotating' and tier = 'beginner' and active;
  if v_n <> 1 then raise exception 'w3 rotating refused: rotating/beginner has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = 'd3d484a7742ad8630b827ee15222bde0' and fields = '[{"key": "escravos_duty_flow_gpm", "tol": 0.0001, "unit": "gpm", "label": "Duty flow, where the pump curve and the station curve cross", "expected": 1250.5424879929428}, {"key": "escravos_duty_head_ft", "tol": 0.00001, "unit": "ft", "label": "Duty head at that flow, which both curves agree on", "expected": 382.18578819518336}, {"key": "escravos_hydraulic_hp", "tol": 0.000001, "unit": "hp", "label": "Hydraulic horsepower delivered to the liquid at duty", "expected": 99.3293593899892}, {"key": "escravos_brake_hp", "tol": 0.000001, "unit": "hp", "label": "Brake horsepower at the shaft, the hydraulic power through the pump efficiency", "expected": 130.52478237843522}, {"key": "escravos_motor_input_kw", "tol": 0.000001, "unit": "kW", "label": "Motor input power at duty", "expected": 103.76579259904362}, {"key": "escravos_discharge_psi", "tol": 5E-7, "unit": "psi", "label": "The duty head expressed as a pressure on this crude", "expected": 136.16402756910645}]'::jsonb then 'old'
              when md5(prompt) = '8c50ade31a8cedcc5933650ccfa7731d' and fields = '[{"key": "escravos_duty_flow_gpm", "tol": 0.0001, "unit": "gpm", "label": "Duty flow, where the pump curve and the station curve cross", "expected": 1250.5424879929428}, {"key": "escravos_duty_head_ft", "tol": 0.00001, "unit": "ft", "label": "Duty head at that flow, which both curves agree on", "expected": 382.18578819518336}, {"key": "escravos_hydraulic_hp", "tol": 0.000001, "unit": "hp", "label": "Hydraulic horsepower delivered to the liquid at duty", "expected": 99.3293593899892}, {"key": "escravos_brake_hp", "tol": 0.000001, "unit": "hp", "label": "Brake horsepower at the shaft, the hydraulic power through the pump efficiency", "expected": 130.52478237843522}, {"key": "escravos_motor_input_kw", "tol": 0.000001, "unit": "kW", "label": "Motor input power at duty", "expected": 103.76579259904362}, {"key": "escravos_discharge_psi", "tol": 5E-7, "unit": "psi", "label": "The duty head expressed as a pressure on this crude", "expected": 136.16402756910645}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'rotating' and tier = 'beginner' and active;
  if v_s0 = 'other' then
    raise exception 'w3 rotating refused: rotating/beginner matches neither its post-W1 form (prompt md5 d3d484a7742ad8630b827ee15222bde0) nor its W3 form (prompt md5 8c50ade31a8cedcc5933650ccfa7731d), with the fields this file was generated against';
  end if;

  -- rotating / intermediate
  select count(*) into v_n from public.academy_capstones where app_slug = 'rotating' and tier = 'intermediate' and active;
  if v_n <> 1 then raise exception 'w3 rotating refused: rotating/intermediate has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '6e3098810e44f03642c471221df846d2' and fields = '[{"key": "bonga_pressure_head_ft", "tol": 5E-7, "unit": "ft", "label": "Pressure head, the suction pressure over vapour pressure as a head of this liquid", "expected": 45.907594936708854}, {"key": "bonga_npsha_ft", "tol": 5E-7, "unit": "ft", "label": "NPSH available on the suction side as surveyed", "expected": 53.10759493670886}, {"key": "bonga_npsha_raised_ft", "tol": 5E-7, "unit": "ft", "label": "NPSH available with the suction drum padded to the proposed pressure", "expected": 130.88734177215187}, {"key": "bonga_speed_flow_gpm", "tol": 0.0001, "unit": "gpm", "label": "Flow of the solved duty carried to the proposed speed by the affinity laws", "expected": 789.6981924270747}, {"key": "bonga_speed_head_ft", "tol": 0.00001, "unit": "ft", "label": "Head of the solved duty carried to the proposed speed by the affinity laws", "expected": 119.05179482935601}, {"key": "bonga_parallel_flow_gpm", "tol": 0.0001, "unit": "gpm", "label": "Duty flow with both machines in parallel against the same station", "expected": 1047.5409037376212}]'::jsonb then 'old'
              when md5(prompt) = '53429a21f7cdc2363e66aafd1c722c34' and fields = '[{"key": "bonga_pressure_head_ft", "tol": 5E-7, "unit": "ft", "label": "Pressure head, the suction pressure over vapour pressure as a head of this liquid", "expected": 45.907594936708854}, {"key": "bonga_npsha_ft", "tol": 5E-7, "unit": "ft", "label": "NPSH available on the suction side as surveyed", "expected": 53.10759493670886}, {"key": "bonga_npsha_raised_ft", "tol": 5E-7, "unit": "ft", "label": "NPSH available with the suction drum padded to the proposed pressure", "expected": 130.88734177215187}, {"key": "bonga_speed_flow_gpm", "tol": 0.0001, "unit": "gpm", "label": "Flow of the solved duty carried to the proposed speed by the affinity laws", "expected": 789.6981924270747}, {"key": "bonga_speed_head_ft", "tol": 0.00001, "unit": "ft", "label": "Head of the solved duty carried to the proposed speed by the affinity laws", "expected": 119.05179482935601}, {"key": "bonga_parallel_flow_gpm", "tol": 0.0001, "unit": "gpm", "label": "Duty flow with both machines in parallel against the same station", "expected": 1047.5409037376212}]'::jsonb then 'new'
              else 'other' end
    into v_s1 from public.academy_capstones where app_slug = 'rotating' and tier = 'intermediate' and active;
  if v_s1 = 'other' then
    raise exception 'w3 rotating refused: rotating/intermediate matches neither its post-W1 form (prompt md5 6e3098810e44f03642c471221df846d2) nor its W3 form (prompt md5 53429a21f7cdc2363e66aafd1c722c34), with the fields this file was generated against';
  end if;

  -- rotating / advanced
  select count(*) into v_n from public.academy_capstones where app_slug = 'rotating' and tier = 'advanced' and active;
  if v_n <> 1 then raise exception 'w3 rotating refused: rotating/advanced has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '0897cf1b8031a37f42545bdc5bc88c72' and fields = '[{"key": "bonny_exponent_ratio", "tol": 5E-10, "unit": "dimensionless", "label": "The polytropic exponent ratio, from k and the polytropic efficiency", "expected": 0.27879592957942817}, {"key": "bonny_ratio_per_stage", "tol": 1E-9, "unit": "dimensionless", "label": "Pressure ratio per stage at the stage count the duty demands", "expected": 2.078966699408976}, {"key": "bonny_stage1_discharge_f", "tol": 0.00005, "unit": "degF", "label": "First stage discharge temperature, from its own inlet at that ratio", "expected": 221.77616024486855}, {"key": "bonny_stage1_poly_head", "tol": 0.01, "unit": "ft lbf per lbm", "label": "First stage polytropic head", "expected": 35027.51189671851}, {"key": "bonny_stage1_gas_hp", "tol": 0.00005, "unit": "hp", "label": "First stage gas horsepower", "expected": 1678.3191179361222}, {"key": "bonny_fuel_mmscfd", "tol": 1E-9, "unit": "MMscfd", "label": "Driver fuel gas for the whole train", "expected": 0.9551900686419833}]'::jsonb then 'old'
              when md5(prompt) = '07c169915342116f4005c226b05052e8' and fields = '[{"key": "bonny_exponent_ratio", "tol": 5E-10, "unit": "dimensionless", "label": "The polytropic exponent ratio, from k and the polytropic efficiency", "expected": 0.27879592957942817}, {"key": "bonny_ratio_per_stage", "tol": 1E-9, "unit": "dimensionless", "label": "Pressure ratio per stage at the stage count the duty demands", "expected": 2.078966699408976}, {"key": "bonny_stage1_discharge_f", "tol": 0.00005, "unit": "degF", "label": "First stage discharge temperature, from its own inlet at that ratio", "expected": 221.77616024486855}, {"key": "bonny_stage1_poly_head", "tol": 0.01, "unit": "ft lbf per lbm", "label": "First stage polytropic head", "expected": 35027.51189671851}, {"key": "bonny_stage1_gas_hp", "tol": 0.00005, "unit": "hp", "label": "First stage gas horsepower", "expected": 1678.3191179361222}, {"key": "bonny_fuel_mmscfd", "tol": 1E-9, "unit": "MMscfd", "label": "Driver fuel gas for the whole train", "expected": 0.9551900686419833}]'::jsonb then 'new'
              else 'other' end
    into v_s2 from public.academy_capstones where app_slug = 'rotating' and tier = 'advanced' and active;
  if v_s2 = 'other' then
    raise exception 'w3 rotating refused: rotating/advanced matches neither its post-W1 form (prompt md5 0897cf1b8031a37f42545bdc5bc88c72) nor its W3 form (prompt md5 07c169915342116f4005c226b05052e8), with the fields this file was generated against';
  end if;

  -- nothing to write: every row is already in its W3 form
  if v_s0 = 'new' and v_s1 = 'new' and v_s2 = 'new' then
    raise notice 'w3 rotating: 0 of 3 row(s) written, all already applied';
    return;
  end if;

  -- W1 (20261024*) must be applied first: its rows are this file's base
  if not exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                  where c.app_slug = 'seismolord' and c.tier = 'intermediate' and c.active and f->>'key' = 'corr_zero_lag')
     or not exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                  where c.app_slug = 'mbal' and c.tier = 'beginner' and c.active and f->>'key' = 'eo_last_rb_stb')
     or not exists (select 1 from public.academy_capstones
                  where app_slug = 'basin' and tier = 'beginner' and active and prompt like 'Open book%') then
    raise exception 'w3 rotating refused: W1 (20261024*) is not applied on this database; apply it first (/root/w1-apply/apply.sh apply --prod)';
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'ESCRAVOS P-1401, the crude transfer pump lifting to the tank farm. The vendor curve is published at 0 gpm and 486 ft, 700 gpm and 452 ft, 1400 gpm and 358 ft, and 2000 gpm and 214 ft. The station stands 168 ft static and takes 214 ft of friction at 1250 gpm. The crude has a specific gravity of 0.823. The pump efficiency agreed with the vendor for this selection is 0.761 and the motor nameplate efficiency is 0.938. The duty is searched to 8000 gpm. Report six values from the duty the two curves reach together, the power that duty costs and the pressure that head represents. Flows in gpm, heads in ft, power in hp and kW, and pressure in psi, to six decimals. Read the figures in the Pump Station Designer with its Full precision switch on (at the top of the page): it prints them to the precision this capstone grades, with no digit grouping.'
     where app_slug = 'rotating' and tier = 'beginner' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w3 rotating refused: rotating/beginner updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '8c50ade31a8cedcc5933650ccfa7731d' and fields = '[{"key": "escravos_duty_flow_gpm", "tol": 0.0001, "unit": "gpm", "label": "Duty flow, where the pump curve and the station curve cross", "expected": 1250.5424879929428}, {"key": "escravos_duty_head_ft", "tol": 0.00001, "unit": "ft", "label": "Duty head at that flow, which both curves agree on", "expected": 382.18578819518336}, {"key": "escravos_hydraulic_hp", "tol": 0.000001, "unit": "hp", "label": "Hydraulic horsepower delivered to the liquid at duty", "expected": 99.3293593899892}, {"key": "escravos_brake_hp", "tol": 0.000001, "unit": "hp", "label": "Brake horsepower at the shaft, the hydraulic power through the pump efficiency", "expected": 130.52478237843522}, {"key": "escravos_motor_input_kw", "tol": 0.000001, "unit": "kW", "label": "Motor input power at duty", "expected": 103.76579259904362}, {"key": "escravos_discharge_psi", "tol": 5E-7, "unit": "psi", "label": "The duty head expressed as a pressure on this crude", "expected": 136.16402756910645}]'::jsonb) from public.academy_capstones where app_slug = 'rotating' and tier = 'beginner' and active) is not true then
    raise exception 'w3 rotating refused: rotating/beginner does not read back as its W3 form';
  end if;

  if v_s1 = 'old' then
    update public.academy_capstones
       set prompt = 'BONGA P-2203, the booster station. The vendor curve is published at 0 gpm and 212 ft, 450 gpm and 198 ft, 900 gpm and 160 ft, and 1300 gpm and 96 ft. The station stands 44 ft static and takes 88 ft of friction at 800 gpm. The liquid has a specific gravity of 0.79. The suction side was surveyed at 19.4 psia against a vapour pressure of 3.7 psia, with the source vessel standing 11.5 ft above the pump and 4.3 ft of friction between them. Two changes are on the table: padding the suction drum to 46.0 psia, and running the machine at 0.87 of rated speed. A debottleneck would put 2 identical machines in parallel against that same station. Every duty is searched to 6000 gpm. Report six values from the suction side as surveyed, the suction side as it would be with the drum padded, the solved duty carried to the proposed speed, and the two machines in parallel. Heads in ft and flows in gpm, to six decimals. Read the figures in the Pump Station Designer with its Full precision switch on (at the top of the page): it prints them to the precision this capstone grades, with no digit grouping.'
     where app_slug = 'rotating' and tier = 'intermediate' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w3 rotating refused: rotating/intermediate updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '53429a21f7cdc2363e66aafd1c722c34' and fields = '[{"key": "bonga_pressure_head_ft", "tol": 5E-7, "unit": "ft", "label": "Pressure head, the suction pressure over vapour pressure as a head of this liquid", "expected": 45.907594936708854}, {"key": "bonga_npsha_ft", "tol": 5E-7, "unit": "ft", "label": "NPSH available on the suction side as surveyed", "expected": 53.10759493670886}, {"key": "bonga_npsha_raised_ft", "tol": 5E-7, "unit": "ft", "label": "NPSH available with the suction drum padded to the proposed pressure", "expected": 130.88734177215187}, {"key": "bonga_speed_flow_gpm", "tol": 0.0001, "unit": "gpm", "label": "Flow of the solved duty carried to the proposed speed by the affinity laws", "expected": 789.6981924270747}, {"key": "bonga_speed_head_ft", "tol": 0.00001, "unit": "ft", "label": "Head of the solved duty carried to the proposed speed by the affinity laws", "expected": 119.05179482935601}, {"key": "bonga_parallel_flow_gpm", "tol": 0.0001, "unit": "gpm", "label": "Duty flow with both machines in parallel against the same station", "expected": 1047.5409037376212}]'::jsonb) from public.academy_capstones where app_slug = 'rotating' and tier = 'intermediate' and active) is not true then
    raise exception 'w3 rotating refused: rotating/intermediate does not read back as its W3 form';
  end if;

  if v_s2 = 'old' then
    update public.academy_capstones
       set prompt = 'BONNY K-3101, the gas booster train. It takes 34.0 MMscfd from 138.0 psia and 96.0 degF up to 1240.0 psia. The gas gravity is 0.673 and k is 1.272. The polytropic efficiency is 0.767 and the mechanical efficiency is 0.972. The maximum ratio per stage is 3.8 and the maximum discharge temperature is 285.0 degF. The intercoolers return the gas to 96.0 degF between stages. The driver has a heat rate of 7650 Btu per hp hr and burns a fuel of 968 Btu per scf. Report six values from the exponent, the staging, the first stage and the driver. Temperatures in degF, heads in ft lbf per lbm and power in hp to four decimals. The exponent ratio, the ratio per stage and the fuel rate in MMscfd to nine decimals. Read the figures in the Compressor Station Designer with its Full precision switch on (at the top of the page): it prints them to the precision this capstone grades, with no digit grouping.'
     where app_slug = 'rotating' and tier = 'advanced' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w3 rotating refused: rotating/advanced updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '07c169915342116f4005c226b05052e8' and fields = '[{"key": "bonny_exponent_ratio", "tol": 5E-10, "unit": "dimensionless", "label": "The polytropic exponent ratio, from k and the polytropic efficiency", "expected": 0.27879592957942817}, {"key": "bonny_ratio_per_stage", "tol": 1E-9, "unit": "dimensionless", "label": "Pressure ratio per stage at the stage count the duty demands", "expected": 2.078966699408976}, {"key": "bonny_stage1_discharge_f", "tol": 0.00005, "unit": "degF", "label": "First stage discharge temperature, from its own inlet at that ratio", "expected": 221.77616024486855}, {"key": "bonny_stage1_poly_head", "tol": 0.01, "unit": "ft lbf per lbm", "label": "First stage polytropic head", "expected": 35027.51189671851}, {"key": "bonny_stage1_gas_hp", "tol": 0.00005, "unit": "hp", "label": "First stage gas horsepower", "expected": 1678.3191179361222}, {"key": "bonny_fuel_mmscfd", "tol": 1E-9, "unit": "MMscfd", "label": "Driver fuel gas for the whole train", "expected": 0.9551900686419833}]'::jsonb) from public.academy_capstones where app_slug = 'rotating' and tier = 'advanced' and active) is not true then
    raise exception 'w3 rotating refused: rotating/advanced does not read back as its W3 form';
  end if;

  raise notice 'w3 rotating: % of 3 row(s) written, % already applied', v_written, 3 - v_written;
end $$;
